public class GridCopierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[][] grid = {{1, 2}, {3, 4}};
        int[][] copy = GridCopier.deepCopy(grid);

        check("copy has the same contents", "[[1, 2], [3, 4]]",
                copy == null ? "null" : java.util.Arrays.deepToString(copy));
        check("outer array is a new object", true, copy != null && copy != grid);
        check("row 0 is a new object (not shared)", true,
                copy != null && copy.length == 2 && copy[0] != grid[0]);

        if (copy != null && copy.length == 2 && copy[0].length == 2) {
            copy[0][0] = 99;
            check("mutating the copy leaves the original alone", 1, grid[0][0]);
            grid[1][1] = 77;
            check("mutating the original leaves the copy alone", 4, copy[1][1]);
        } else {
            check("mutating the copy leaves the original alone", 1, null);
            check("mutating the original leaves the copy alone", 4, null);
        }

        int[][] jagged = {{5}, {6, 7, 8}};
        int[][] jaggedCopy = GridCopier.deepCopy(jagged);
        check("jagged rows copy correctly", "[[5], [6, 7, 8]]",
                jaggedCopy == null ? "null" : java.util.Arrays.deepToString(jaggedCopy));

        int[][] empty = new int[0][0];
        int[][] emptyCopy = GridCopier.deepCopy(empty);
        check("empty grid copies to []", "[]",
                emptyCopy == null ? "null" : java.util.Arrays.deepToString(emptyCopy));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

