public class GridCopier {

    public static int[][] deepCopy(int[][] grid) {
        int[][] copy = new int[grid.length][];
        for (int i = 0; i < grid.length; i++) {
            copy[i] = new int[grid[i].length];
            for (int j = 0; j < grid[i].length; j++) {
                copy[i][j] = grid[i][j];
            }
        }
        return copy;
    }
}
